; ============================================================================
; runtime_debug.asm -- 2.5.0 debugging support: SEH crash handler
;
; The compiler inserts `call _yxg_debug_install` at the start of _main when -g.
; On a crash:
;   1. take the exception address and module base, compute the module RVA
;   2. read <exe>.map  (generated by dwmap.c)
;        line 1: "# yxg dbgmap v1"
;        line 2: "# src <source file name>"
;        then  : "<hex RVA> <line> <function>"
;   3. pick the largest entry with RVA <= fault RVA, print file:line (func)
;   4. walk the EBP chain, and for each frame do the same lookup
;
; All output is ASCII on purpose: console code page differences must not
; corrupt the diagnostic text.
; ============================================================================
    global _yxg_debug_install

extern _SetUnhandledExceptionFilter@4
extern _GetModuleHandleA@4
extern _GetModuleFileNameA@12
extern _CreateFileA@28
extern _GetFileSize@8
extern _ReadFile@20
extern _CloseHandle@4
extern _WriteFile@20
extern _GetStdHandle@4

STD_ERROR_HANDLE equ -12
GENERIC_READ     equ 0x80000000
OPEN_EXISTING    equ 3
FILE_SHARE_READ  equ 1
INVALID_HANDLE   equ -1
MAP_MAX          equ 65536
CTX_EBP          equ 180
MAX_FRAMES       equ 8

section .data
dbg_map_suffix  db '.map', 0
dbg_txt_crash   db 13, 10, '*** CRASH ***', 13, 10, 0
dbg_txt_at      db '  fault address : 0x', 0
dbg_txt_off     db '  module offset : 0x', 0
dbg_txt_loc     db '  source        : ', 0
dbg_txt_colon   db ':', 0
dbg_txt_func    db '   (in ', 0
dbg_txt_paren   db ')', 13, 10, 0
dbg_txt_nomap   db '  (no .map file - recompile with -g)', 13, 10, 0
dbg_txt_unk     db '  (address not covered by debug map)', 13, 10, 0
dbg_txt_stack   db '  stack:', 13, 10, 0
dbg_txt_arrow   db '    0x', 0
dbg_txt_indent  db '       ', 0
dbg_txt_nl      db 13, 10, 0
dbg_txt_stkend  db '    ...', 13, 10, 0
dbg_txt_unknown db 'unknown.yxg', 0
dbg_hexchars    db '0123456789ABCDEF', 0

section .bss
dbg_path_buf    resb 512
dbg_map_buf     resb MAP_MAX
dbg_out_buf     resb 64
dbg_nwritten    resd 1
dbg_hfile       resd 1
dbg_fsize       resd 1
dbg_imgn        resd 1
dbg_imgsize     resd 1
dbg_fault       resd 1
dbg_off         resd 1
dbg_best_off    resd 1
dbg_best_line   resd 1
dbg_best_name   resb 128
dbg_srcname     resb 260
dbg_have_map    resd 1

section .text

; ---------------------------------------------------------------------------
; void yxg_debug_install(void)
; ---------------------------------------------------------------------------
_yxg_debug_install:
    push ebp
    mov  ebp, esp
    push ebx
    push ecx
    push edx

    ; remember module base and image size (PE optional header offset 56)
    push 0
    call _GetModuleHandleA@4
    mov  ebx, eax
    mov  [dbg_imgn], eax
    mov  dword [dbg_imgsize], 0
    test ebx, ebx
    jz   .no_size
    mov  ecx, [ebx + 0x3C]
    add  ecx, ebx
    cmp  dword [ecx], 0x00004550     ; 'PE\0\0'
    jne  .no_size
    mov  edx, [ecx + 24 + 56]        ; SizeOfImage
    mov  [dbg_imgsize], edx
.no_size:
    push dbg_handler
    call _SetUnhandledExceptionFilter@4

    pop  edx
    pop  ecx
    pop  ebx
    pop  ebp
    ret

; ---------------------------------------------------------------------------
; dbg_puts: write the NUL-terminated string at esi to stderr
; ---------------------------------------------------------------------------
dbg_puts:
    push ebx
    push edx
    mov  ebx, esi
    xor  edx, edx
.len:
    cmp  byte [ebx + edx], 0
    je   .have
    inc  edx
    jmp  .len
.have:
    test edx, edx
    jz   .done
    push STD_ERROR_HANDLE
    call _GetStdHandle@4
    mov  dword [dbg_nwritten], 0
    push 0
    push dbg_nwritten
    push edx
    push ebx
    push eax
    call _WriteFile@20
.done:
    pop  edx
    pop  ebx
    ret

; ---------------------------------------------------------------------------
; dbg_puthex8: print eax as 8 hex digits
; ---------------------------------------------------------------------------
dbg_puthex8:
    push ebx
    push ecx
    mov  ebx, eax
    mov  ecx, 8
.loop:
    rol  ebx, 4
    mov  eax, ebx
    and  eax, 0x0F
    mov  al, [dbg_hexchars + eax]
    mov  [dbg_out_buf], al
    mov  byte [dbg_out_buf + 1], 0
    push ecx
    mov  esi, dbg_out_buf
    call dbg_puts
    pop  ecx
    dec  ecx
    jnz  .loop
    pop  ecx
    pop  ebx
    ret

; ---------------------------------------------------------------------------
; dbg_putdec: print eax as unsigned decimal
; ---------------------------------------------------------------------------
dbg_putdec:
    push ebx
    push ecx
    push edx
    lea  ebx, [dbg_out_buf + 32]
    mov  byte [ebx], 0
    mov  ecx, 10
    test eax, eax
    jnz  .loop
    dec  ebx
    mov  byte [ebx], '0'
    jmp  .out
.loop:
    xor  edx, edx
    div  ecx
    add  dl, '0'
    dec  ebx
    mov  [ebx], dl
    test eax, eax
    jnz  .loop
.out:
    mov  esi, ebx
    call dbg_puts
    pop  edx
    pop  ecx
    pop  ebx
    ret

; ---------------------------------------------------------------------------
; dbg_parse_src: find a line starting with "# src " and copy the rest into
; dbg_srcname.  Compares byte by byte (no string library available).
; ---------------------------------------------------------------------------
dbg_parse_src:
    push esi
    push edi
    push ecx
    push edx
    mov  esi, dbg_map_buf
    mov  edi, [dbg_fsize]
    cmp  edi, 8
    jl   .done
.scan:
    cmp  edi, 6
    jl   .done
    cmp  byte [esi], '#'
    jne  .next
    cmp  byte [esi + 1], ' '
    jne  .next
    cmp  byte [esi + 2], 's'
    jne  .next
    cmp  byte [esi + 3], 'r'
    jne  .next
    cmp  byte [esi + 4], 'c'
    jne  .next
    cmp  byte [esi + 5], ' '
    jne  .next
    add  esi, 6
    jmp  .found
.next:
    inc  esi
    dec  edi
    jmp  .scan
.found:
    mov  edi, dbg_srcname
    mov  ecx, 259
.cp:
    test ecx, ecx
    jz   .end
    mov  al, [esi]
    cmp  al, 13
    je   .end
    cmp  al, 10
    je   .end
    cmp  al, 0
    je   .end
    mov  [edi], al
    inc  esi
    inc  edi
    dec  ecx
    jmp  .cp
.end:
    mov  byte [edi], 0
.done:
    pop  edx
    pop  ecx
    pop  edi
    pop  esi
    ret

; ---------------------------------------------------------------------------
; dbg_lookup: find the largest map entry with RVA <= dbg_off
; results: dbg_best_off / dbg_best_line / dbg_best_name  (-1 when no match)
; ---------------------------------------------------------------------------
dbg_lookup:
    push ebx
    push esi
    push edi
    push ebp
    push edx
    mov  dword [dbg_best_off], -1

    ; reject addresses that fall outside this module
    mov  eax, [dbg_imgsize]
    test eax, eax
    jz   .in_range
    cmp  [dbg_off], eax
    jae  .fin
.in_range:
    mov  esi, dbg_map_buf
    mov  edi, [dbg_fsize]
.scan:
    test edi, edi
    jle  .fin
    mov  al, [esi]
    cmp  al, '#'
    je   .eol
    cmp  al, 13
    je   .skip_one
    cmp  al, 10
    je   .skip_one

    ; ---- 8 hex digits -> ebp ----
    xor  ebp, ebp
    mov  ecx, 8
.hex:
    test edi, edi
    jle  .fin
    mov  al, [esi]
    inc  esi
    dec  edi
    cmp  al, '0'
    jb   .eol
    cmp  al, '9'
    jbe  .dig
    or   al, 0x20
    cmp  al, 'a'
    jb   .eol
    cmp  al, 'f'
    ja   .eol
    sub  al, 'a' - 10
    jmp  .acc
.dig:
    sub  al, '0'
.acc:
    shl  ebp, 4
    movzx eax, al
    add  ebp, eax
    dec  ecx
    jnz  .hex

    ; ---- skip spaces ----
.sp:
    test edi, edi
    jle  .fin
    cmp  byte [esi], ' '
    jne  .dec
    inc  esi
    dec  edi
    jmp  .sp

    ; ---- decimal line number -> ebx ----
.dec:
    xor  ebx, ebx
.decl:
    test edi, edi
    jle  .cmp
    mov  al, [esi]
    cmp  al, '0'
    jb   .cmp
    cmp  al, '9'
    ja   .cmp
    imul ebx, ebx, 10
    sub  al, '0'
    movzx eax, al
    add  ebx, eax
    inc  esi
    dec  edi
    jmp  .decl

    ; ---- compare and maybe record ----
.cmp:
    cmp  ebp, [dbg_off]
    ja   .eol
    cmp  dword [dbg_best_off], -1
    je   .take
    cmp  ebp, [dbg_best_off]
    jbe  .eol
.take:
    mov  [dbg_best_off], ebp
    mov  [dbg_best_line], ebx
    mov  edx, dbg_best_name
    mov  ecx, 127
.cn:
    test ecx, ecx
    jz   .cnd
    test edi, edi
    jle  .cnd
    mov  al, [esi]
    cmp  al, 13
    je   .cnd
    cmp  al, 10
    je   .cnd
    cmp  al, 0
    je   .cnd
    mov  [edx], al
    inc  edx
    inc  esi
    dec  edi
    dec  ecx
    jmp  .cn
.cnd:
    mov  byte [edx], 0
.eol:
    test edi, edi
    jle  .fin
    mov  al, [esi]
    inc  esi
    dec  edi
    cmp  al, 10
    jne  .eol
    jmp  .scan
.skip_one:
    inc  esi
    dec  edi
    jmp  .scan
.fin:
    pop  edx
    pop  ebp
    pop  edi
    pop  esi
    pop  ebx
    ret

; ---------------------------------------------------------------------------
; dbg_print_site: print "<src>:<line>   (in <func>)" from dbg_best_*
; ---------------------------------------------------------------------------
dbg_print_site:
    push esi
    mov  esi, dbg_srcname
    cmp  byte [esi], 0
    jne  .have_src
    mov  esi, dbg_txt_unknown
.have_src:
    call dbg_puts
    mov  esi, dbg_txt_colon
    call dbg_puts
    mov  eax, [dbg_best_line]
    call dbg_putdec
    mov  esi, dbg_txt_func
    call dbg_puts
    mov  esi, dbg_best_name
    call dbg_puts
    mov  esi, dbg_txt_paren
    call dbg_puts
    pop  esi
    ret

; ---------------------------------------------------------------------------
; LONG WINAPI dbg_handler(EXCEPTION_POINTERS* p)
; ---------------------------------------------------------------------------
dbg_handler:
    push ebp
    mov  ebp, esp
    push ebx
    push esi
    push edi
    sub  esp, 32

    mov  dword [dbg_have_map], 0
    mov  byte [dbg_srcname], 0

    ; ---- fault address ----
    mov  eax, [ebp + 8]
    mov  eax, [eax]                  ; EXCEPTION_RECORD*
    mov  eax, [eax + 12]             ; ExceptionAddress
    mov  [dbg_fault], eax

    push 0
    call _GetModuleHandleA@4
    mov  [dbg_imgn], eax

    mov  esi, dbg_txt_crash
    call dbg_puts
    mov  esi, dbg_txt_at
    call dbg_puts
    mov  eax, [dbg_fault]
    call dbg_puthex8
    mov  esi, dbg_txt_nl
    call dbg_puts

    mov  eax, [dbg_fault]
    sub  eax, [dbg_imgn]
    mov  [dbg_off], eax
    mov  esi, dbg_txt_off
    call dbg_puts
    mov  eax, [dbg_off]
    call dbg_puthex8
    mov  esi, dbg_txt_nl
    call dbg_puts

    ; ---- open <exe>.map ----
    push 512
    push dbg_path_buf
    push 0
    call _GetModuleFileNameA@12
    test eax, eax
    jz   .no_map

    lea  edi, [dbg_path_buf]
    xor  ecx, ecx
.find_end:
    cmp  byte [edi + ecx], 0
    je   .append
    inc  ecx
    jmp  .find_end
.append:
    lea  edi, [dbg_path_buf + ecx]
    mov  esi, dbg_map_suffix
.cp_suffix:
    mov  al, [esi]
    mov  [edi], al
    test al, al
    jz   .open
    inc  esi
    inc  edi
    jmp  .cp_suffix
.open:
    push 0
    push 0
    push OPEN_EXISTING
    push 0
    push FILE_SHARE_READ
    push GENERIC_READ
    push dbg_path_buf
    call _CreateFileA@28
    cmp  eax, INVALID_HANDLE
    je   .no_map
    mov  [dbg_hfile], eax

    push 0
    push eax
    call _GetFileSize@8
    cmp  eax, MAP_MAX
    jbe  .size_ok
    mov  eax, MAP_MAX
.size_ok:
    mov  [dbg_fsize], eax
    mov  dword [dbg_nwritten], 0
    push 0
    push dbg_nwritten
    push dword [dbg_fsize]
    push dbg_map_buf
    push dword [dbg_hfile]
    call _ReadFile@20

    push dword [dbg_hfile]
    call _CloseHandle@4

    mov  dword [dbg_have_map], 1
    call dbg_parse_src
    call dbg_lookup

    cmp  dword [dbg_best_off], -1
    je   .not_found

    mov  esi, dbg_txt_loc
    call dbg_puts
    call dbg_print_site
    jmp  .stack

.not_found:
    mov  esi, dbg_txt_unk
    call dbg_puts
    jmp  .stack

.no_map:
    mov  esi, dbg_txt_nomap
    call dbg_puts

.stack:
    mov  esi, dbg_txt_stack
    call dbg_puts

    mov  eax, [ebp + 8]
    mov  eax, [eax + 4]              ; CONTEXT*
    test eax, eax
    jz   .stack_end
    mov  edi, [eax + CTX_EBP]
    mov  ebx, MAX_FRAMES
.pop_loop:
    test edi, edi
    jz   .stack_end
    test edi, 3
    jnz  .stack_end
    mov  eax, [edi + 4]              ; return address
    test eax, eax
    jz   .stack_end

    push edi
    push ebx

    mov  esi, dbg_txt_arrow
    call dbg_puts
    mov  eax, [edi + 4]
    push eax
    call dbg_puthex8
    pop  eax

    cmp  dword [dbg_have_map], 0
    je   .frame_no_line
    sub  eax, [dbg_imgn]
    mov  [dbg_off], eax
    call dbg_lookup
    cmp  dword [dbg_best_off], -1
    je   .frame_no_line
    mov  esi, dbg_txt_indent
    call dbg_puts
    call dbg_print_site
    jmp  .frame_next
.frame_no_line:
    mov  esi, dbg_txt_nl
    call dbg_puts
.frame_next:
    pop  ebx
    pop  edi
    mov  edi, [edi]
    dec  ebx
    jnz  .pop_loop
    mov  esi, dbg_txt_stkend
    call dbg_puts
.stack_end:
    mov  esi, dbg_txt_nl
    call dbg_puts

    xor  eax, eax                    ; EXCEPTION_CONTINUE_SEARCH
    add  esp, 32
    pop  edi
    pop  esi
    pop  ebx
    pop  ebp
    ret
